cssScreen:
.pv{font:var(--type-body-size)/var(--type-body-line-height) var(--font-body);color:var(--color-text-primary);background:var(--color-bg-primary)}
.pv *{box-sizing:border-box}
.vt{padding:20px 24px;display:flex;flex-direction:column;gap:22px;background:var(--color-bg-primary)}
.pv[data-platform=mobile] .vt{padding:16px}
.vh{font:600 12px/16px var(--font-body);color:var(--color-text-tertiary_strong);margin-bottom:8px;display:flex;gap:8px;align-items:baseline}
.vh small{font:400 12px/16px var(--font-body);color:var(--color-text-disabled)}
.vg{display:flex;flex-wrap:wrap;gap:12px;align-items:center}
.vgrid{display:grid;gap:10px 14px;align-items:center}
.vl{font:500 11px/14px var(--font-code);color:var(--color-text-disabled);white-space:nowrap}
.card{background:var(--color-bg-primary);border:1px solid var(--color-border-secondary);border-radius:var(--radius-card)}
.pv .muted{color:var(--color-text-tertiary)}
.pg{padding:20px 24px}
.pv[data-platform=mobile] .pg{padding:16px}
.tbl{width:100%;border-collapse:collapse}
.tbl th,.tbl td{padding:10px 16px;border-bottom:1px solid var(--color-border-secondary);text-align:left;font-size:12px;line-height:16px;vertical-align:middle}
.tbl th{color:var(--color-text-tertiary);font-weight:500;background:var(--color-bg-secondary)}
.row{display:flex;align-items:center;gap:12px}
.sp{flex:1}
.mono{font-family:var(--font-code);font-size:12px}
.sec-t{font:600 14px/20px var(--font-body);margin:0 0 4px}

.cell{display:grid;place-items:center;height:120px;overflow:visible;border:1px dashed var(--color-border-secondary);border-radius:var(--radius-md);background:var(--color-bg-secondary)}
.cell .anc>.tt{white-space:nowrap}
.cell.tall{height:168px}
.dotx{width:24px;height:24px;border-radius:6px;background:var(--color-bg-primary);border:1px solid var(--color-border-primary)}
/* màn demo */
.ib{display:inline-grid;place-items:center;width:32px;height:32px;border-radius:var(--radius-control);border:1px solid var(--color-border-secondary);background:var(--color-bg-primary);color:var(--color-fg-tertiary)}
.ib.on{background:var(--color-bg-primary_hover);color:var(--color-fg-secondary)}
.fld{display:flex;flex-direction:column;gap:6px;max-width:320px}
.fld .lb{display:flex;align-items:center;gap:4px;font:500 12px/16px var(--font-body);color:var(--color-text-tertiary_strong)}
.fld .in{height:32px;border:1px solid var(--color-border-input);border-radius:var(--radius-field);padding:0 10px;display:flex;align-items:center;background:var(--field-bg)}
.fld .hint{font-size:12px;line-height:16px;color:var(--color-text-tertiary)}
.grid2{display:grid;grid-template-columns:1fr 1fr;gap:20px 24px;max-width:700px}
.toolbar{display:flex;gap:8px;align-items:center;padding:0 24px 12px}
.trunc{max-width:180px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;display:inline-block;vertical-align:middle}
/* khung tĩnh cho bảng biến thể mobile */
.mfr{position:relative;height:440px;overflow:hidden;background:var(--color-bg-primary)}
/* màn chi tiết */
.dh{display:flex;align-items:center;gap:8px;margin-bottom:16px}.dh .mono{font:600 18px/24px var(--font-code)}
.kv{display:grid;grid-template-columns:160px 1fr;gap:10px 16px;max-width:640px;font-size:14px;line-height:20px}.kv dt{color:var(--color-text-tertiary)}.kv dd{margin:0;min-width:0}
.trunc.w320{max-width:320px}
.mf{padding:16px;display:flex;flex-direction:column;gap:16px}
.mf .lb{display:flex;align-items:center;gap:6px;font:500 12px/16px var(--font-body);color:var(--color-text-tertiary)}
.mf .in{height:52px;border-radius:var(--radius-field);background:var(--field-bg);display:flex;align-items:center;padding:0 16px;font-size:16px}
/* nhãn, lưới của bảng biến thể + khung khối preview */
.vl6{margin-bottom:6px}.g4{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.r48{gap:48px;align-items:flex-start}.vgt{align-items:flex-start}
.pvp{padding:16px}.mf0{padding:0}.mb14{margin-bottom:14px}.m0{margin:0}

.sec-t.il-margin-bottom-14{margin-bottom:14px}
.sec-t.il-margin-0{margin:0}
